float vrchCoverageRadius(float coverage) {
  return sqrt(coverage / 3.14159265359) + 0.145 * pow(smoothstep(0.785, 1.0, coverage), 3.0);
}
float vrchColorDot(vec2 point, float angle, float density, float coverage, float dotSize) {
  float cs = cos(angle);
  float sn = sin(angle);
  vec2 rotated = vec2(point.x * cs - point.y * sn, point.x * sn + point.y * cs);
  vec2 local = fract(rotated * density) - 0.5;
  float baseRadius = vrchCoverageRadius(pow(clamp(coverage, 0.0, 1.0), uParam_contrast));
  float radius = clamp(baseRadius * dotSize, 0.0, 0.7071);
  float distanceToCenter = length(local);
  float antialias = max(fwidth(distanceToCenter) * 1.5, 0.002);
  return 1.0 - smoothstep(radius - antialias, radius + antialias, distanceToCenter);
}
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
  vec2 uv = fragCoord / iResolution.xy;
  vec4 image = vrchSampleSource0(uv);
  vec2 aspect = vec2(iResolution.x / iResolution.y, 1.0);
  vec2 toneGrid = uv * aspect * uParam_density;
  vec2 toneUv = (floor(toneGrid) + 0.5) / (aspect * uParam_density);
  vec3 tone = vrchSampleSource0(clamp(toneUv, vec2(0.0), vec2(1.0))).rgb;
  vec2 point = (uv - 0.5) * aspect;
  float turn = uParam_angle * 6.28318530718;
  float cyan = vrchColorDot(point, turn + 0.261799, uParam_density, 1.0 - tone.r, uParam_dot_size);
  float magenta = vrchColorDot(point, turn + 1.308997, uParam_density, 1.0 - tone.g, uParam_dot_size);
  float yellow = vrchColorDot(point, turn, uParam_density, 1.0 - tone.b, uParam_dot_size);
  vec3 absorption = vec3(cyan, magenta, yellow) * uParam_ink;
  vec3 printed = uParam_paper.rgb * (vec3(1.0) - clamp(absorption, 0.0, 0.92));
  float treatment = uParam_amount;
  fragColor = vec4(mix(image.rgb, printed, treatment), image.a);
}
